import{obterJSON,endereco,consultaLimpa,pontuarCorrespondencia}from'./comum.js';
const texto=(el,nome)=>el.getElementsByTagNameNS('*',nome)[0]?.textContent?.replace(/\s+/g,' ').trim()||'';
const textos=(el,nome)=>[...el.getElementsByTagNameNS('*',nome)].map(x=>x.textContent?.replace(/\s+/g,' ').trim()).filter(Boolean);
export function converterArxiv(entry){
 const idUrl=texto(entry,'id'),id=idUrl.match(/\/abs\/([^?#]+)/)?.[1]||idUrl.split('/').pop();if(!id)return null;
 const titulo=texto(entry,'title')||'Sem título',autores=[...entry.getElementsByTagNameNS('*','author')].map(a=>texto(a,'name')).filter(Boolean),resumo=texto(entry,'summary'),publicado=texto(entry,'published');
 const links=[...entry.getElementsByTagNameNS('*','link')],alternativo=links.find(l=>l.getAttribute('rel')==='alternate')?.getAttribute('href'),pdfLink=links.find(l=>/pdf/i.test(l.getAttribute('type')||'')||/pdf/i.test(l.getAttribute('title')||''))?.getAttribute('href');
 const pagina=endereco(alternativo)||endereco(`https://arxiv.org/abs/${id}`),pdf=endereco(pdfLink)||endereco(`https://arxiv.org/pdf/${id}`);if(!pagina)return null;
 return{id:`arxiv:${id}`,fonte:'arxiv',provedor:'arXiv',titulo,autores,idiomas:[],capa:null,descricao:[resumo,publicado?`Publicado em ${publicado.slice(0,10)}`:''].filter(Boolean).join(' · '),acessoLivre:true,dominioPublico:false,tipoAcesso:'Preprint / artigo acadêmico · acesso aberto',licenca:'O arXiv oferece acesso gratuito ao texto. A licença de reutilização varia por trabalho e deve ser conferida no registro.',origem:pagina,ler:pagina,texto:null,formatos:pdf?[{tipo:'PDF',url:pdf}]:[]};
}
export async function pesquisarArxiv(q,o={}){const termo=consultaLimpa(q);if(!termo)return{livros:[],total:0,temMais:false};const pagina=Math.max(1,o.pagina||1),u=new URL('/api/acervos-gratuitos',location.origin);u.searchParams.set('fonte','arxiv');u.searchParams.set('q',termo);u.searchParams.set('pagina',String(pagina));const d=await obterJSON(u,15000,3),doc=new DOMParser().parseFromString(String(d?.xml||''),'application/xml');if(doc.querySelector('parsererror'))throw new Error('arXiv devolveu XML inválido');const entries=[...doc.getElementsByTagNameNS('*','entry')],livros=entries.map(converterArxiv).filter(Boolean);for(const l of livros)l.relevancia=pontuarCorrespondencia(termo,l.titulo,l.autores);livros.sort((a,b)=>(b.relevancia||0)-(a.relevancia||0));const total=Number(doc.getElementsByTagNameNS('*','totalResults')[0]?.textContent)||livros.length;return{livros,total,temMais:pagina*20<total&&entries.length>0}}
